<script setup lang="ts">
import { appLocalMode } from '../../lib/app-mode';
import { appPath } from '../../lib/app-path';
import { computed, ref } from 'vue';
import { ArrowUpRight, Clock3, FileImage, FolderOpen, LoaderCircle, Plus, RefreshCw, Search, X } from '@lucide/vue';
import { categories, categoryFor, moduleSection, needsAI, type ProductCategory, type Project } from '../../lib/design-model';

const localMode = appLocalMode();
const props = defineProps<{ projects: Project[]; loading: boolean; error: string; busy: boolean }>();
const emit = defineEmits<{ open: [project: Project]; create: [output: 'main' | 'detail']; retry: [] }>();
const search = ref('');
const category = ref<'all' | ProductCategory>('all');
const output = ref<'all' | 'main' | 'detail'>('all');
const filtered = computed(() => props.projects.filter(project => {
  const query = search.value.trim().toLocaleLowerCase();
  const searchable = `${project.info.name} ${project.info.brand}`.toLocaleLowerCase();
  const kinds = new Set(project.modules.map(module => module.kind));
  const matchesOutput = output.value === 'all' || project.output === output.value || !project.output && (kinds.has(output.value) || !kinds.size && output.value === 'main');
  return (!query || searchable.includes(query)) && (category.value === 'all' || categoryFor(project).id === category.value) && matchesOutput;
}).sort((a, b) => b.updatedAt.localeCompare(a.updatedAt)));
const isFiltered = computed(() => !!search.value.trim() || category.value !== 'all' || output.value !== 'all');
function clearFilters() { search.value = ''; category.value = 'all'; output.value = 'all'; }
function cover(project: Project) {
  const hero = project.modules.find(module => moduleSection(module) === 'hero');
  return project.assets.find(asset => asset.id === hero?.imageId) || project.assets.find(asset => !asset.generated);
}
function state(project: Project) {
  if (!project.modules.length) return { text: '待完善资料', tone: 'draft' };
  if (project.workflow === 'plan') return { text: '待确认计划', tone: 'draft' };
  if (project.modules.some(module => module.aiStatus === 'failed')) return { text: '图片需重试', tone: 'error' };
  if (project.workflow === 'preview') return { text: '待确认首图', tone: 'draft' };
  if (project.generation === 'ai' && project.modules.some(module => needsAI(project, module) && module.aiStatus !== 'succeeded')) return { text: '图片待生成', tone: 'pending' };
  return project.workflow === 'complete' || project.status === 'ready' ? { text: '已完成排版', tone: 'ready' } : { text: '制作中', tone: 'draft' };
}
function outputName(project: Project) {
  if (project.output === 'main') return '商品主图';
  if (project.output === 'detail') return '商品详情';
  const kinds = new Set(project.modules.map(module => module.kind));
  return kinds.size > 1 ? '主图 + 详情' : kinds.has('detail') ? '商品详情' : '商品主图';
}
function date(value: string) {
  const d = new Date(value);
  return Number.isNaN(d.getTime()) ? '已保存' : d.toLocaleDateString('zh-CN', { month: 'long', day: 'numeric' });
}
</script>

<template>
  <div class="works-library">
    <header class="page-heading"><div><span class="eyebrow">YOUR PRODUCT COLLECTION</span><h1>作品，越做越好。</h1><p>把每次创作留下来，随时接着完善。</p></div><button class="primary-button" :disabled="busy" @click="emit('create', 'main')"><Plus :size="16" /> 新建作品</button></header>
    <div class="toolbar"><div class="tabs" aria-label="按图片用途筛选"><button :aria-pressed="output === 'all'" @click="output = 'all'">全部作品 <span>{{ projects.length }}</span></button><button :aria-pressed="output === 'main'" @click="output = 'main'">商品主图</button><button :aria-pressed="output === 'detail'" @click="output = 'detail'">商品详情</button></div><div class="tools"><label class="search-input"><Search :size="15" /><input v-model="search" type="search" placeholder="搜索商品名称或品牌" aria-label="搜索商品名称或品牌" /><button v-if="search" aria-label="清空搜索" @click="search = ''"><X :size="13" /></button></label><label class="category-select"><span class="sr-only">筛选商品类目</span><select v-model="category"><option value="all">全部类目</option><option v-for="item in categories" :key="item.id" :value="item.id">{{ item.name }}</option></select></label></div></div>
    <div class="results-line"><p>{{ isFiltered ? '筛选结果' : '所有作品' }} <span>{{ filtered.length }} 件</span></p><button v-if="isFiltered" @click="clearFilters">清除筛选 <X :size="12" /></button><span v-else>最近保存的作品排在前面</span></div>
    <div v-if="loading" class="state-panel" role="status"><LoaderCircle class="spin" :size="24" /><p>{{ localMode ? '正在读取本地作品…' : '正在读取服务器作品…' }}</p></div>
    <div v-else-if="error" class="state-panel error" role="alert"><FolderOpen :size="31" /><h2>作品列表暂时无法加载</h2><p>{{ error }}</p><button class="secondary-button" :disabled="busy" @click="emit('retry')"><RefreshCw :size="15" /> 重新加载</button></div>
    <div v-else-if="!filtered.length" class="state-panel"><span class="empty-icon"><FolderOpen :size="31" /></span><h2>{{ isFiltered ? '还没有符合条件的作品' : '这里，留给你的第一件作品。' }}</h2><p>{{ isFiltered ? '试试其他关键词，或清除筛选查看全部作品。' : '上传商品实拍，制作并保存你的主图或详情。' }}</p><button v-if="isFiltered" class="secondary-button" @click="clearFilters">清除筛选</button><button v-else class="primary-button" :disabled="busy" @click="emit('create', 'main')"><Plus :size="15" /> 开始新作品</button></div>
    <div v-else class="works-grid"><button v-for="project in filtered" :key="project.id" class="work-card" :disabled="busy" @click="emit('open', project)"><span class="work-art"><img v-if="cover(project)" :src="appPath(cover(project)!.url)" :alt="project.info.name || '商品素材'" loading="lazy" /><FileImage v-else :size="37" /><span class="work-kind">{{ outputName(project) }}</span><span class="open-label">继续编辑 <ArrowUpRight :size="15" /></span></span><span class="work-content"><span class="work-title"><strong>{{ project.info.name || '未命名商品' }}</strong><span class="status" :class="state(project).tone"><i />{{ state(project).text }}</span></span><span class="work-meta">{{ categoryFor(project).name }} <span>·</span> {{ project.modules.length ? `${project.modules.length} 张图片` : `${project.assets.filter(asset => !asset.generated).length} 张实拍` }}</span><span class="work-footer"><small><Clock3 :size="12" /> {{ date(project.updatedAt) }}保存</small><span>{{ project.info.brand || '商品作品' }}</span></span></span></button></div>
  </div>
</template>

